'use strict';
let state, view='overview', selected=null, detailTab='analysis', inboxId=null, reviewFilter='PENDING', dirty=false;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>s?new Date(s).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}):'—';
const initial=s=>esc(s.split(/\s+/).slice(0,2).map(w=>w[0]).join('').toUpperCase());
const names={NEW:'Novo',RESEARCHING:'Em pesquisa',QUALIFIED:'Qualificado',CONTACT_PENDING:'Pronto para contato',CONTACTED:'Contatado',REPLIED:'Respondeu',INTERESTED:'Interessado',MEETING:'Reunião',PROPOSAL:'Proposta',WON:'Cliente',LOST:'Perdido',FOLLOW_UP:'Follow-up',REPLY:'Resposta à conversa',NOT_INTERESTED:'Sem interesse',PENDING:'Aguardando revisão',APPROVED:'Aprovada',USED:'Utilizada',SUPERSEDED:'Substituída',REJECTED:'Rejeitada',CANCELLED:'Cancelada',DRAFT:'Rascunho',ACTIVE:'Ativa',PAUSED:'Pausada',COMPLETED:'Concluída',READY:'Preparada',QUEUED:'Na fila',SENDING:'Enviando',SENT:'Enviada',FAILED:'Falha',UNKNOWN:'Resultado incerto',BLOCKED:'Bloqueada',CONFIRMED_MANUALLY:'Conferida manualmente',NOT_SENT:'Não enviada',LANDING_PAGE:'Landing page',WEBSITE:'Site institucional',CONTENT:'Conteúdo estratégico',AI_ATTENDANT:'Assistente de IA',AUTOMATION:'Automação',HIGH_PRIORITY:'Alta prioridade',OPPORTUNITY:'Oportunidade',NO_CLEAR_OPPORTUNITY:'Em investigação',EXCLUDED:'Fora do perfil'};
const translate=s=>names[s]||s;
const pill=(s,color)=>`<span class="pill ${color||(['QUALIFIED','APPROVED','SENT','ACTIVE','WON'].includes(s)?'green':['FAILED','BLOCKED','UNKNOWN','REJECTED'].includes(s)?'red':['PENDING','PAUSED','CONTACT_PENDING'].includes(s)?'amber':'gray')}">${esc(translate(s))}</span>`;
const empty=(title,description,action='')=>`<div class="empty"><div class="empty-icon">◎</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;
const field=(name,label,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function notify(text){$('#notice').textContent=text}
async function api(path,data){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json','X-Requested-With':'ProspectLocal'},body:JSON.stringify(data)});if(response.status===401){window.location.replace('/login');throw Error('Sua sessão expirou. Entre novamente.')}const result=await response.json();if(!response.ok)throw Error(result.error||'Falha na operação.');return result.result}
async function refresh(){const response=await fetch('/api/state');if(response.status===401){window.location.replace('/login');return}if(!response.ok)throw Error('Não foi possível atualizar os dados.');state=await response.json();render();if(selected)detail(selected)}
function setView(next){if(dirty&&!confirm('Descartar alterações ainda não salvas?'))return;dirty=false;view=next;render();window.scrollTo(0,0)}
function metrics(items){return `<div class="metrics">${items.map(([label,value,icon,foot])=>`<div class="card metric"><div class="metric-top">${esc(label)}<span class="metric-icon">${icon}</span></div><strong class="metric-number">${esc(value)}</strong><div class="metric-foot">${esc(foot)}</div></div>`).join('')}</div>`}
function table(leads){if(!leads.length)return empty('Sua próxima oportunidade começa aqui','Adicione leads ou importe uma base para pesquisar, qualificar e acompanhar cada conversa.','<button data-view="import" class="primary">＋ Adicionar leads</button>');return `<div class="table-wrap"><table><thead><tr><th>EMPRESA</th><th>OPORTUNIDADE</th><th>SCORE</th><th>ETAPA</th><th>PRÓXIMA AÇÃO</th><th></th></tr></thead><tbody>${leads.map(l=>`<tr data-lead="${l.id}" tabindex="0"><td><div class="company-cell"><span class="company-logo">${initial(l.company)}</span><div><strong>${esc(l.company)}</strong><small>${esc(l.data.niche||'Nicho não informado')} ${l.data.city?' · '+esc(l.data.city):''}</small></div></div></td><td>${l.analysis?.opportunities.length?pill(translate(l.analysis.opportunities[0].service),''):l.analysis?.qualified?pill(l.analysis.classification,l.analysis.classification==='HIGH_PRIORITY'?'green':''):'<span class="caption">Em investigação</span>'}</td><td><span class="score">${l.score}</span></td><td>${l.do_not_contact?pill('Não contatar','red'):pill(l.status)}</td><td>${esc(l.data.next_action||'Revisar contexto')}</td><td>↗</td></tr>`).join('')}</tbody></table></div>`}
function contactQueue(leads){return leads.filter(l=>l.analysis?.qualified&&!l.do_not_contact&&['QUALIFIED','CONTACT_PENDING'].includes(l.status)&&!l.messages.some(m=>m.state==='USED')&&l.messages.some(m=>['A','B','C'].includes(m.variant)&&['PENDING','APPROVED'].includes(m.state))).sort((a,b)=>b.score-a.score||a.id-b.id)}
function agendaToday(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function agendaLeads(leads){return leads.filter(l=>!l.do_not_contact&&!['WON','LOST','NOT_INTERESTED'].includes(l.status)&&l.data.next_action).sort((a,b)=>(a.data.next_action_due||'9999').localeCompare(b.data.next_action_due||'9999')||b.score-a.score||a.id-b.id)}
const meetingNames={SCHEDULED:'Agendada',HELD:'Realizada',NO_SHOW:'Não compareceu',CANCELLED:'Cancelada'};
function meetingForm(l){const m=l.meeting||{};return `<form id="meeting-form" class="card"><h3>Reunião e resultado</h3><p class="caption">Uma entrega qualificada exige reunião realizada, decisor de agência de marketing e necessidade compatível. Este registro acompanha a reunião atual do lead; alterações ficam no histórico.</p><div class="form-grid"><label>Situação<select name="state">${Object.entries(meetingNames).map(([key,label])=>`<option value="${key}" ${m.state===key?'selected':''}>${label}</option>`).join('')}</select></label>${field('date','Data da reunião',m.date||'','date','required')}${field('participant','Nome e cargo do participante',m.participant||'')}${field('need','Necessidade identificada',m.need||'')}</div>${[['decision_maker','Participou um decisor'],['agency_fit','É uma agência de marketing'],['compatible_need','A necessidade é compatível com a oferta']].map(([key,label])=>`<label class="check-label"><input name="${key}" type="checkbox" ${m[key]?'checked':''}>${label}</label>`).join('')}<label>Notas<textarea name="notes">${esc(m.notes||'')}</textarea></label><p>${m.qualified?pill('Entrega qualificada','green'):pill('Ainda não contabilizada como entrega','gray')}</p><button class="primary">Salvar reunião</button></form>`}
function connectionCard(){return `<div class="connection-card"><span class="instagram-icon">◎</span><div><strong>Instagram</strong><p>API oficial · Conta profissional</p></div>${pill(state.instagram.ready?'Pronto para uso':state.instagram.configured?'Envio desabilitado':'Conectar conta',state.instagram.ready?'green':'amber')}</div>`}
function render(){if(!state)return;const m=state.metrics;const headings={meetings:['Reuniões e entregas','Acompanhe reuniões realizadas e qualificadas pelo critério da SantX Digital.'],agenda:['Agenda de próximas ações','Organize responsáveis e prazos para acompanhar cada lead.'],contact_queue:['Fila de contato','Priorize leads qualificados e revise as abordagens antes de entrar em contato.'],prospecting:['Prospecção no Instagram','Encontre candidatos, confira evidências e prepare a primeira abordagem.'],overview:['Visão geral','Transforme boas conversas em novas oportunidades.'],leads:['Seus leads','Contexto, oportunidade e um próximo passo para cada negócio.'],pipeline:['Pipeline comercial','Acompanhe cada relacionamento do primeiro contato à proposta.'],review:['Central de revisão','Mensagens personalizadas, evidências claras e controle de qualidade.'],campaigns:['Campanhas','Uma autorização. Textos definidos. Envios dentro dos seus limites.'],inbox:['Conversas','Organize os contatos que chegam ao seu Instagram.'],report:['Resultados','Dados reais para entender o que funciona na sua prospecção.'],import:['Adicionar leads','Comece com uma empresa ou traga sua base existente.'],settings:['Configurações','Ajuste sua agência, o perfil ideal e as integrações.']};const [title,sub]=headings[view];$('#title').textContent=title;$('#crumb').textContent=title;$('#subtitle').textContent=sub;$('#agency-label').textContent=state.config.agency_name;$('#lead-count').textContent=m.leads;$('#connection-label').textContent=state.instagram.ready?'Envio habilitado':'Conexão pendente';$('.connection-dot').classList.toggle('ready',state.instagram.ready);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));let html='';
if(view==='overview'){
 const unresolved=state.leads.filter(l=>!l.analysis?.qualified&&!l.do_not_contact).length;
 html=metrics([['Leads na base',m.leads,'♧','Empresas registradas'],['Leads qualificados',m.qualified,'✓','Com oportunidade e evidência'],['Contatos realizados',m.contacted,'↗','Registrados manualmente ou pela API'],['Taxa de resposta',m.response_rate+'%','☷','Respostas entre leads contatados']]);
 html+=`<div class="banner"><span class="banner-symbol">✦</span><div><strong>${state.instagram.ready?'Sua operação está pronta para avançar':'Conecte sua conta. Centralize suas conversas.'}</strong><p>${state.instagram.ready?'Revise os textos e autorize sua próxima campanha para conversas elegíveis.':'O Instagram oficial responde a quem iniciou uma conversa. Configure a integração para habilitar o envio real.'}</p></div><button data-view="${state.instagram.ready?'campaigns':'settings'}">${state.instagram.ready?'Ver campanhas':'Configurar Instagram'} ↗</button></div>`;
 html+=`<div class="dashboard-grid"><div class="card"><div class="section-head"><div><h3>Panorama comercial</h3><p>Contagens reais por etapa · sem previsões de compra</p></div><span class="pill gray">Todos os leads</span></div><div class="funnel">${[['Leads na base',m.leads],['Qualificados',m.qualified],['Contatados',m.contacted],['Responderam',m.replies],['Clientes',m.won]].map(([label,value])=>`<div class="funnel-row"><span>${label}</span><progress max="${Math.max(1,m.leads,m.replies)}" value="${value}" aria-label="${label}"></progress><strong>${value}</strong></div>`).join('')}</div><div class="mini-stats"><span>REUNIÕES<strong>${m.meetings}</strong></span><span>PROPOSTAS<strong>${m.proposals}</strong></span><span>CONVERSÃO<strong>${m.conversion_rate}%</strong></span></div></div><div class="card"><div class="section-head"><h3>Sua fila de prioridades</h3><span class="pill">Agora</span></div>${[['⌕','Pesquisar leads',unresolved,'Completar contexto e evidências','leads'],['✓','Revisar mensagens',state.daily.pending_messages,'Conferir observações e abordagem','review'],['◷','Acompanhar conversas',state.daily.due_followups,'Follow-ups que chegaram à data','review'],['◎','Conectar Instagram',state.instagram.ready?0:1,'Habilitar a operação real','settings']].map(([icon,label,count,desc,target])=>`<div class="queue-item"><span class="queue-icon">${icon}</span><div><strong>${label}</strong><p>${desc}</p></div><span class="count">${count}</span><button data-view="${target}" aria-label="${label}">›</button></div>`).join('')}</div></div><div class="card"><div class="section-head"><div><h3>Oportunidades prioritárias</h3><p>Leads qualificados ordenados por score operacional</p></div><button data-view="leads">Ver todos ↗</button></div>${table(state.leads.filter(l=>l.analysis?.qualified&&!l.do_not_contact).slice(0,6))}</div>`;
}
if(view==='leads')html=`<div class="row toolbar"><input id="search" placeholder="⌕ Buscar empresa, nicho ou cidade" aria-label="Buscar leads"><select id="lead-filter" aria-label="Filtrar leads"><option value="all">Todos os leads</option><option value="qualified">Qualificados</option><option value="research">Precisam de pesquisa</option><option value="eligible">Instagram elegível</option></select><span class="caption trailing">${m.leads} empresas na base</span></div><div class="card" id="lead-table">${table(state.leads)}</div>`;
if(view==='contact_queue'){
const queue=contactQueue(state.leads);
html=metrics([['Prontos para revisão',queue.length,'✓','Leads qualificados ainda sem contato'],['Alta prioridade',queue.filter(l=>l.analysis.classification==='HIGH_PRIORITY').length,'◎','Classificação calculada pelo score'],['Com abordagem aprovada',queue.filter(l=>l.messages.some(m=>['A','B','C'].includes(m.variant)&&m.state==='APPROVED')).length,'↗','Aprovação não significa envio']])+`<div class="card"><div class="section-head"><div><h3>Próximos contatos</h3><p>Maior score primeiro. Abra um lead para revisar suas abordagens A/B/C. Nenhuma mensagem é enviada por esta fila.</p></div></div>${queue.length?table(queue):empty('Nenhum lead aguardando contato','Leads qualificados com abordagens pendentes ou aprovadas aparecerão aqui.')}</div>`;
}
if(view==='agenda'){
const leads=agendaLeads(state.leads),today=agendaToday();
html=metrics([['Atrasadas',leads.filter(l=>l.data.next_action_due&&l.data.next_action_due<today).length,'◷','Prazo anterior a hoje'],['Para hoje',leads.filter(l=>l.data.next_action_due===today).length,'◎','Ações com prazo hoje'],['Sem prazo',leads.filter(l=>!l.data.next_action_due).length,'♧','Defina uma data no lead']])+`<div class="card"><div class="section-head"><div><h3>Próximas ações</h3><p>Abra um lead e acesse CRM para salvar a ação, o responsável e o prazo.</p></div></div>${leads.length?`<div class="table-wrap"><table><thead><tr><th>EMPRESA</th><th>PRÓXIMA AÇÃO</th><th>RESPONSÁVEL</th><th>PRAZO</th><th>SITUAÇÃO</th></tr></thead><tbody>${leads.map(l=>{const due=l.data.next_action_due;return `<tr data-lead="${l.id}" tabindex="0"><td>${esc(l.company)}</td><td>${esc(l.data.next_action)}</td><td>${esc(l.data.owner||'Não definido')}</td><td>${due?esc(due.split('-').reverse().join('/')):'Sem prazo'}</td><td>${pill(!due?'Sem prazo':due<today?'Atrasada':due===today?'Hoje':'Agendada',due&&due<today?'red':due===today?'amber':'gray')}</td></tr>`}).join('')}</tbody></table></div>`:empty('Nenhuma ação agendada','Abra um lead e defina o próximo passo na aba CRM.')}</div>`;
}
if(view==='meetings'){
const leads=state.leads.filter(l=>l.meeting).sort((a,b)=>b.meeting.date.localeCompare(a.meeting.date)||a.id-b.id);
html=metrics([['Agendadas',leads.filter(l=>l.meeting.state==='SCHEDULED').length,'◷','Ainda não são entregas'],['Realizadas',leads.filter(l=>l.meeting.state==='HELD').length,'✓','Reuniões que aconteceram'],['Entregas qualificadas',leads.filter(l=>l.meeting.qualified).length,'◎','Realizadas com todos os critérios']])+`<div class="card"><h3>Reuniões por lead</h3><p>Abra um lead na aba CRM para registrar ou atualizar sua reunião. Uma entrega por lead; reagendamentos atualizam o mesmo registro.</p>${leads.length?`<div class="table-wrap"><table><thead><tr><th>EMPRESA</th><th>DATA</th><th>PARTICIPANTE</th><th>SITUAÇÃO</th><th>ENTREGA</th></tr></thead><tbody>${leads.map(l=>`<tr data-lead="${l.id}" tabindex="0"><td>${esc(l.company)}</td><td>${esc(l.meeting.date.split('-').reverse().join('/'))}</td><td>${esc(l.meeting.participant||'Não informado')}</td><td>${esc(meetingNames[l.meeting.state])}</td><td>${pill(l.meeting.qualified?'Qualificada':'Não contabilizada',l.meeting.qualified?'green':'gray')}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma reunião registrada','Registre a primeira reunião na aba CRM de um lead.')}</div>`;
}
if(view==='pipeline')html=`<div class="kanban">${state.statuses.map(status=>{const leads=state.leads.filter(l=>l.status===status);return `<div class="column"><h3>${esc(translate(status))}<span class="pill gray">${leads.length}</span></h3>${leads.map(l=>`<div class="card" data-lead="${l.id}" tabindex="0"><div class="company-cell"><span class="company-logo">${initial(l.company)}</span><strong>${esc(l.company)}</strong></div><p>${esc(l.data.niche||'Nicho não informado')}</p><span class="score">${l.score} pontos</span><p>${esc(l.data.next_action||'Definir próximo passo')}</p></div>`).join('')||'<div class="empty">Nenhum lead nesta etapa</div>'}</div>`}).join('')}</div>`;
if(view==='import')html=`<div class="grid"><form id="create" class="card"><div class="section-head"><div><h3>Uma boa pesquisa começa com contexto</h3><p>Dados públicos comerciais ou informações fornecidas por você</p></div></div><div class="form-grid">${field('company','Empresa *','','text','required maxlength="120"')}${field('name','Contato comercial')}${field('niche','Nicho')}${field('city','Cidade')}${field('instagram','Instagram','', 'text','placeholder="@empresa"')}${field('website','Site','','text','placeholder="https://"')}${field('email','E-mail comercial','','email')}${field('phone','Telefone comercial')}<label class="wide">Oferta principal<textarea name="offer" placeholder="O que essa empresa oferece?"></textarea></label>${field('audience','Público-alvo')}${field('source','Origem da pesquisa','manual')}</div><div class="save-bar"><button class="primary">Cadastrar e analisar ↗</button></div></form><div><div class="card"><h3>Importar sua base</h3><p class="muted">CSV com até 1000 linhas e 2 MB. Empresa é o único campo obrigatório. Registros duplicados são preservados na base e ignorados na importação.</p><div class="file-drop"><div class="empty-icon">⇧</div><strong>Selecione seu arquivo CSV</strong><input type="file" id="csv" accept=".csv" aria-label="Arquivo CSV"></div><p class="caption">Colunas: company, name, instagram, website, email, phone, city, niche, source.</p><button id="import-csv" class="primary">Importar e analisar</button><div id="import-result" class="import-result"></div></div><div class="card"><h3>Da informação à oportunidade</h3><div class="steps"><div class="step"><div><strong>Registre uma observação real</strong><p>Identifique oferta, público e pontos específicos do negócio.</p></div></div><div class="step"><div><strong>Guarde a fonte da pesquisa</strong><p>Um sinal só produz oportunidade quando há fonte e observação.</p></div></div><div class="step"><div><strong>Revise e escolha a abordagem</strong><p>A análise separa fatos de hipóteses e prepara três opções.</p></div></div></div></div></div></div>`;
if(view==='review'){
const messages=state.leads.flatMap(l=>l.messages.filter(msg=>msg.state===reviewFilter).map(msg=>({l,msg}))).slice(0,100);
html=`<div class="page-tabs">${['PENDING','APPROVED','REJECTED'].map(s=>`<button data-review-filter="${s}" class="${reviewFilter===s?'active':''}">${esc(translate(s))}</button>`).join('')}</div>${messages.map(({l,msg})=>messageCard(l,msg)).join('')||`<div class="card">${empty('Sua revisão está em dia','As mensagens aparecem aqui após qualificar um lead com evidências.','<button data-view="leads">Pesquisar leads ↗</button>')}</div>`}`;
}
if(view==='campaigns'){
const eligible=state.leads.filter(l=>!state.eligibility[String(l.id)]&&l.messages.some(m=>['PENDING','APPROVED'].includes(m.state)&&m.variant!=='FOLLOW_UP'));
html=`<div class="banner"><span class="banner-symbol">↗</span><div><strong>Envio autorizado por campanha</strong><p>A autorização cobre os destinatários e os textos apresentados abaixo. Alterações ou novas respostas interrompem os itens afetados.</p></div><span class="pill ${state.instagram.ready?'green':'amber'}">${state.instagram.ready?'Integração pronta':'Conexão pendente'}</span></div><div class="card"><div class="section-head"><div><h3>Preparar uma campanha</h3><p>Somente conversas recebidas, vinculadas e dentro da janela operacional de 24 horas</p></div><span class="pill">${eligible.length} elegíveis</span></div>${eligible.length?`<form id="campaign-create"><div class="form-grid">${field('name','Nome da campanha','','text','required placeholder="Ex.: Conversas da semana"')}${field('daily_limit','Limite por dia',Math.min(10,state.config.max_daily_actions),'number',`min="1" max="${state.config.max_daily_actions}" required`)}${field('interval_seconds','Intervalo entre envios (segundos)',60,'number','min="30" max="86400" required')}</div>${eligible.map(l=>{const messages=l.messages.filter(m=>['PENDING','APPROVED'].includes(m.state)&&m.variant!=='FOLLOW_UP');return `<div class="campaign-select"><input type="checkbox" name="lead" value="${l.id}" aria-label="Selecionar ${esc(l.company)}"><span class="company-logo">${initial(l.company)}</span><div><strong>${esc(l.company)}</strong><small>${esc(l.data.niche||'Nicho não informado')}</small></div><select data-campaign-message="${l.id}" aria-label="Abordagem para ${esc(l.company)}">${messages.map(m=>`<option value="${m.id}">${esc(variant(m.variant))}</option>`).join('')}</select></div><div id="campaign-preview-${l.id}" class="message-preview">${esc(messages[0].body)}</div>`}).join('')}<div class="save-bar"><button class="primary">Criar rascunho para revisão ↗</button></div></form>`:empty('Ainda não há conversas elegíveis','Conecte o Instagram, receba uma mensagem, vincule a conversa ao lead e prepare uma abordagem com evidências.','<button data-view="inbox">Ir para conversas ↗</button>')}</div>${state.campaigns.map(c=>`<div class="card"><div class="section-head"><div><h3>${esc(c.name)}</h3><p>${c.daily_limit} envios/dia · ${c.interval_seconds}s de intervalo · ${c.items.length} destinatários</p></div>${pill(c.state)}</div>${c.note?`<p class="invalid">${esc(c.note)}</p>`:''}${c.items.map(item=>`<div class="campaign-item"><div class="heading-inline"><strong>${esc(item.company)}</strong>${pill(item.state)}</div><p>${esc(item.body)}</p><div class="caption">Revisão: ${item.review.passed?'checklist passou':'ajustes necessários'} · ${esc(item.review.engine)}</div>${item.review.issues.length?`<p class="invalid">${esc(item.review.issues.join(' · '))}</p>`:''}${item.error?`<p class="invalid">${esc(item.error)}</p>`:''}${item.state==='UNKNOWN'?`<div class="actions"><button data-reconcile="${item.id}" data-campaign="${c.id}" data-outcome="sent">Conferi: mensagem foi enviada</button><button data-reconcile="${item.id}" data-campaign="${c.id}" data-outcome="not_sent">Conferi: mensagem não foi enviada</button></div>`:''}</div>`).join('')}<p class="caption">${c.authorized_at?'Autorizada em '+date(c.authorized_at)+' · válida até '+date(c.expires_at):'Nenhum envio autorizado ainda.'}</p><div class="actions">${['DRAFT','PAUSED'].includes(c.state)?`<button data-campaign="${c.id}" data-campaign-action="authorize" class="primary" ${state.instagram.ready?'':'disabled'}>Autorizar textos e iniciar envios</button>`:''}${c.state==='ACTIVE'?`<button data-campaign="${c.id}" data-campaign-action="pause">Pausar campanha</button>`:''}${!['COMPLETED','CANCELLED'].includes(c.state)?`<button data-campaign="${c.id}" data-campaign-action="cancel" class="danger">Cancelar campanha</button>`:''}</div></div>`).join('')}`;
}
if(view==='inbox'){
 const contact=state.inbox.find(c=>c.recipient_id===inboxId)||state.inbox[0];if(contact)inboxId=contact.recipient_id;
html=`${connectionCard()}${contact?`<div class="inbox-grid"><div class="conversation-list">${state.inbox.map(c=>{const lead=state.leads.find(l=>l.id===c.lead_id);return `<button data-inbox="${esc(c.recipient_id)}" class="${inboxId===c.recipient_id?'active':''}">${esc(lead?.company||'Conversa não vinculada')}<small>${date(c.last_inbound_at)}</small>${c.suppressed?'<small>Contato bloqueado</small>':''}</button>`}).join('')}</div><div class="card"><div class="section-head"><div><h3>${esc(state.leads.find(l=>l.id===contact.lead_id)?.company||'Vincular esta conversa')}</h3><p>ID recebido pela Meta: ${esc(contact.recipient_id)}</p></div>${pill(contact.suppressed?'Bloqueada':'Recebida',contact.suppressed?'red':'green')}</div><form id="automatic-contact"><p class="caption">${esc(contact.automatic_reason||(state.config.automatic_inbox?.enabled?'Automação disponível para novas mensagens.':'Automação global desativada.'))}</p><button>${contact.automatic_paused?'Retomar automação para novas mensagens':'Assumir conversa e pausar automação'}</button></form>${!contact.lead_id?`<form id="inbox-link"><label>Lead do CRM<select name="lead_id" required><option value="">Selecione a empresa correspondente</option>${state.leads.map(l=>`<option value="${l.id}">${esc(l.company)}</option>`).join('')}</select></label><button>Vincular conversa</button><p class="caption">Confirme a identidade do contato antes de vincular.</p></form>`:`<button data-lead="${contact.lead_id}">Abrir perfil do lead ↗</button>`}<div class="actions"></div>${contact.lead_id?`<div class="card reply-compose"><h3>Responder esta conversa</h3><p class="caption">${esc(contact.reply_reason||'Prepare a resposta, confira o texto e autorize o envio.')}</p>${!contact.reply_reason?`<form id="inbox-reply"><label>Resposta<textarea name="body" required maxlength="1000" rows="4">${esc('Olá! Obrigado por entrar em contato com a Agência Santx. Como podemos ajudar?')}</textarea></label><p class="caption">Sugestão por modelo local. Edite conforme a mensagem recebida; não invente preços ou informações.</p><button class="primary">Revisar e preparar resposta</button></form>`:''}${state.campaigns.filter(c=>['DRAFT','ACTIVE','PAUSED'].includes(c.state)&&c.items.some(i=>i.recipient_id===contact.recipient_id&&state.leads.find(l=>l.id===i.lead_id)?.messages.some(m=>m.id===i.message_id&&m.variant==='REPLY'))).map(c=>`<div class="message-preview">${c.items.map(i=>`<p>${esc(i.body)}</p><small>${esc(translate(i.state))}${i.error?' · '+esc(i.error):''}</small>`).join('')}<div class="actions">${['DRAFT','PAUSED'].includes(c.state)&&c.items.some(i=>['READY','QUEUED'].includes(i.state))?`<button class="primary" data-campaign="${c.id}" data-campaign-action="authorize">Autorizar esta resposta e enviar</button>`:''}<button data-view="campaigns">Ver campanha e status</button></div></div>`).join('')}</div>`:''}${state.campaigns.flatMap(c=>c.items.filter(i=>i.recipient_id===contact.recipient_id&&['SENT','CONFIRMED_MANUALLY'].includes(i.state)).map(i=>`<div class="bubble"><strong>Resposta enviada</strong><p>${esc(i.body)}</p><small>${date(c.last_dispatch_at||c.authorized_at)} · ${i.state==='SENT'?'Aceita pela Meta':'Conferida manualmente'}</small></div>`)).join('')}${contact.events.map(e=>`<div class="bubble">${esc(e.body)}<small>${date(e.occurred_at)} · Recebida pelo Instagram</small></div>`).join('')}</div></div>`:`<div class="card">${empty('As conversas vão aparecer aqui','Receba mensagens por webhook autenticado do Instagram. Não usamos eventos simulados como conversas reais.','<button data-view="settings" class="primary">Configurar integração ↗</button>')}</div>`}`;
}
if(view==='prospecting'){const p=state.prospecting;html=`<div class="banner"><div><strong>Primeira abordagem manual pelo Instagram</strong><p>Esta fila usa perfis indexados em busca pública. A ausência de um site não é confirmada automaticamente. O atendimento automático assume quando o contato responder.</p></div></div><form id="prospect-search" class="card"><h3>Buscar candidatos</h3><p class="caption">${p.remaining_searches} buscas disponíveis neste mês no limite local.</p><div class="form-grid"><label>Nicho<select name="niche"><option value="advogado">Advogados</option><option value="médico">Médicos</option><option value="agencia_marketing">Agências de Marketing</option></select></label>${field('city','Cidade','Manaus','text','required maxlength="80"')}</div><p class="caption">${p.configured?'Tavily conectada: busca básica, até 20 resultados. Limite local de 100 consultas mensais.':'Busca ainda não conectada. Configure TAVILY_API_KEY no arquivo .env e reinicie o Orbit. Nenhum resultado fictício será exibido.'}</p><button class="primary" ${p.configured?'':'disabled'}>Buscar perfis públicos</button></form><form id="prospect-schedule" class="card"><h3>Captação diária de candidatos</h3><p>Uma busca por advogados e uma por médicos por dia, em UTC, enquanto o Orbit estiver ligado. Até 20 resultados por busca. A verificação e a primeira DM continuam manuais.</p>${field('city','Cidade da captação diária',p.schedule.city||'Manaus','text','required maxlength="80"')}<label class="check-label"><input type="checkbox" name="enabled" ${p.schedule.enabled?'checked':''} ${p.configured?'':'disabled'}>Ativar duas buscas diárias dentro do limite local</label><button ${p.configured?'':'disabled'}>Salvar captação diária</button>${p.runs.map(r=>`<p class="caption">${esc(r.day)} · ${esc(r.niche)} · ${esc(r.city)} · ${esc(r.state)} · ${esc(r.detail)}</p>`).join('')}</form>${metrics([['Abordagens preparadas',p.candidates.filter(c=>c.approach).length,'↗','Para você enviar manualmente'],['Candidatos pesquisados',p.candidates.filter(c=>c.research?.status).length,'◎','Fatos e oportunidades separados']])}${p.candidates.map(c=>`<div class="card"><div class="section-head"><div><h3>${esc(c.company)}</h3><p>@${esc(c.username)} · Busca por ${esc(c.niche)} em ${esc(c.city)}</p></div><span class="pill">${esc(c.research?.status|| (c.state==='READY'?'Abordagem preparada':'Site e conteúdo não verificados'))}</span></div>${prospectResearch(c)}<p>${esc(c.snippet||'Sem descrição disponível na busca.')}</p><p class="caption">${esc(c.source)} · ${date(c.created_at)}</p><div class="actions"><a class="primary" href="${esc(c.profile_url)}" target="_blank" rel="noopener">Abrir perfil no Instagram ↗</a></div><details><summary>Conferir evidência e preparar outra abordagem</summary><form class="prospect-review" data-prospect="${c.id}">${field('company','Nome do negócio confirmado',c.company,'text','required maxlength="200"')}<label>Serviço a oferecer<select name="service"><option value="WEBSITE" ${c.service==='WEBSITE'?'selected':''}>Site</option><option value="LANDING_PAGE" ${c.service==='LANDING_PAGE'?'selected':''}>Landing page</option><option value="CONTENT" ${c.service==='CONTENT'?'selected':''}>Posts estratégicos</option></select></label>${field('evidence_url','URL da fonte observada',c.evidence_url||c.profile_url,'url','required')}<label>Observação concreta<textarea name="observation" required maxlength="500" placeholder="Ex.: O link da bio abre apenas o WhatsApp; não encontrei um site próprio nos links que conferi.">${esc(c.observation)}</textarea></label><label class="check-label"><input name="verified" type="checkbox" required>Conferi pessoalmente a fonte e esta observação</label><button>Preparar abordagem com esta evidência</button></form></details>${c.approach?`<div class="message-preview"><p>${esc(c.approach)}</p><button data-copy-prospect="${c.id}">Copiar abordagem para envio manual</button></div>`:''}<div class="actions"><button data-reject-prospect="${c.id}">Descartar candidato</button></div></div>`).join('')||empty('Nenhum candidato na fila','Conecte a busca e escolha o nicho e a cidade. Resultados encontrados ainda exigem verificação antes da abordagem.')}`;}
if(view==='report')html=metrics([['Novos leads hoje',state.daily.found,'＋','Dia de referência em UTC'],['Analisados hoje',state.daily.analyzed,'⌕','Leads únicos analisados'],['Reuniões',m.meetings,'◷','No estágio de reunião'],['Clientes',m.won,'✓','No estágio de ganho']])+`<div class="grid"><div class="card"><h3>Saúde da operação</h3>${[['Data do relatório',state.daily.date_utc+' · UTC'],['Mensagens aguardando revisão',state.daily.pending_messages],['Follow-ups vencidos',state.daily.due_followups],['Falhas internas hoje',state.daily.errors.length],['Campanhas ativas',state.campaigns.filter(c=>c.state==='ACTIVE').length],['Envios com confirmação Meta',state.campaigns.flatMap(c=>c.items).filter(i=>i.state==='SENT').length]].map(([a,b])=>`<div class="health-line"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`).join('')}</div><div class="card"><h3>Entenda seus resultados</h3><div class="health-line"><span>Taxa de resposta</span><strong>${m.response_rate}%</strong></div><div class="health-line"><span>Taxa de conversão</span><strong>${m.conversion_rate}%</strong></div><p class="muted">Resposta = leads com resposta registrada entre os contatados. Conversão = clientes no estágio ganho sobre a base total. Reuniões, propostas e clientes refletem o estágio atual.</p><p class="caption">Mudanças de estratégia exigem revisão. A aplicação não altera automaticamente regras críticas a partir desses números.</p></div></div><div class="card"><div class="section-head"><h3>Atividade e auditoria</h3><span class="pill gray">Últimos 100 eventos</span></div>${state.logs.map(e=>`<div class="timeline-event"><strong>${esc(eventName(e.action))}</strong><small>${date(e.created_at)}</small><p>${esc(e.detail||'Operação registrada no histórico.')}</p></div>`).join('')||empty('Histórico pronto para registrar','Cada ação importante será registrada aqui.')}</div>`;
if(view==='settings')html=`<div class="grid"><form id="settings" class="card"><h3>Seu workspace</h3>${field('agency_name','Nome da agência',state.config.agency_name,'text','required maxlength="80"')}<div class="form-grid">${field('min_lead_score','Score mínimo para qualificação',state.config.min_lead_score,'number','min="0" max="100" required')}${field('max_daily_actions','Limite global de contatos por dia',state.config.max_daily_actions,'number','min="1" max="100" required')}</div><label>Modo de operação<select name="mode">${['MANUAL','ASSISTIDO','AUTOMATIZADO'].map(mode=>`<option value="${mode}" ${state.config.mode===mode?'selected':''}>${mode==='MANUAL'?'Manual — analisar':mode==='ASSISTIDO'?'Assistido — analisar e preparar':'Automatizado — processar campanhas autorizadas'}</option>`).join('')}</select></label>${field('target_niches','Nichos prioritários (separados por vírgula)',state.config.target_niches.join(', '))}${field('excluded_niches','Nichos excluídos (separados por vírgula)',state.config.excluded_niches.join(', '))}<p class="caption">Salvar pausa campanhas ativas. Reavalie os leads para aplicar novos critérios. Campanhas de prospecção exigem autorização. O atendimento automático usa o roteiro ativado abaixo.</p><div class="save-bar"><button class="primary">Salvar configurações</button></div></form><div class="card"><h3>Conexão com Instagram</h3>${connectionCard()}<div class="steps"><div class="step"><div><strong>Conta profissional e aplicativo Meta</strong><p>Configure Instagram Login e a permissão de mensagens. Para usuários reais fora dos papéis de teste, confira os requisitos de revisão do seu app.</p></div></div><div class="step"><div><strong>Credenciais no arquivo local .env</strong><p>Configure token, ID da conta, versão da API, segredo do app e token de verificação. Nunca coloque sua senha do Instagram.</p></div></div><div class="step"><div><strong>Webhook HTTPS</strong><p>Exponha somente <code>/webhooks/instagram</code> por um proxy HTTPS autorizado, mantendo a interface local. Inscreva o app em mensagens.</p></div></div><div class="step"><div><strong>Habilite e autorize</strong><p>Defina <code>INSTAGRAM_SEND_ENABLED=true</code>, reinicie o servidor e autorize uma campanha com destinatários e textos revisados.</p></div></div></div>${state.instagram.missing.length?`<p class="caption">Pendências locais: ${state.instagram.missing.map(k=>`<code>${esc(k)}</code>`).join(' ')}</p>`:''}<p class="caption">Conexão local configurada não confirma aprovação ou validade do token na Meta. Um envio de teste autorizado ainda é necessário.</p><a href="https://www.postman.com/meta/instagram/documentation/6yqw8pt/instagram-api" target="_blank" rel="noopener">Documentação oficial Meta ↗</a></div></div><div class="grid"><div class="card"><h3>Revisão adicional por IA</h3><div class="health-line"><span>Motor atual</span><strong>${esc(state.ai.engine)}</strong></div><p class="muted">O checklist local revisa tamanho, personalização, hipótese e linguagem. A revisão OpenAI opcional confere alegações e adequação antes da autorização de uma campanha.</p><p class="caption">No .env: <code>AI_PROVIDER=openai</code>, <code>OPENAI_API_KEY</code> e <code>OPENAI_MODEL</code>. A chave fica no backend. Quando ativa, uma revisão indisponível bloqueia a autorização.</p></div><div class="card"><h3>Perfis e serviços</h3>${state.config.icps.map(i=>`<div class="health-line"><span>${esc(i.name)}</span><strong>${esc(translate(i.service))}</strong></div>`).join('')}<p class="caption">Novos perfis, sinais e pesos podem ser adicionados em config.json. O score é operacional; ele não prevê compra.</p></div></div>`;
if(view==='settings'){const a=state.config.automatic_inbox||{};html+=`<form id="automatic-settings" class="card"><h3>Atendimento automático do Instagram</h3><p>Responde às novas mensagens recebidas usando o roteiro abaixo. Perguntas sobre preço ou funcionamento são encaminhadas para você. Conversas encaminhadas ficam pausadas até você retomá-las.</p><label class="check-label"><input type="checkbox" name="enabled" ${a.enabled?'checked':''}>Ativar envio automático conforme este roteiro</label>${field('agency','Nome usado nas respostas',a.agency||'Agência Santx','text','required maxlength="80"')}${field('services','Serviços oferecidos',a.services||'Sites, landing pages e posts estratégicos','text','required maxlength="280"')}${field('question','Pergunta inicial',a.question||'Você procura um site, uma landing page ou posts estratégicos para o seu negócio?','text','required maxlength="280"')}${field('handoff','Resposta ao encaminhar para você',a.handoff||'Vou encaminhar sua solicitação para a equipe da Agência Santx. O atendimento humano responderá assim que estiver disponível.','text','required maxlength="280"')}<div class="form-grid">${field('per_contact_limit','Máximo de respostas por contato por dia',a.per_contact_limit||5,'number','min="1" max="10" required')}${field('interval_seconds','Intervalo mínimo global (segundos)',a.interval_seconds||60,'number','min="30" max="3600" required')}</div><p class="caption">Roteiro local, sem geração livre por IA. O limite global de envios e a janela de atendimento continuam valendo. Salvar cancela pendências automáticas anteriores; mensagens antigas não iniciam atendimento.</p><button class="primary">Salvar roteiro e ativação</button></form>`;}
if(view==='inbox'){const count=state.inbox.filter(c=>c.automatic_paused).length;html=`<div class="banner"><div><strong>${state.config.automatic_inbox?.enabled?'Atendimento automático ativo':'Atendimento automático desativado'}</strong><p>${count?count+' conversa(s) aguardando sua atenção.':'Perguntas sobre valores ou funcionamento serão encaminhadas para você.'}</p></div><button data-view="settings">Configurar atendimento</button></div>`+html;}
$('#content').innerHTML=html;bindForms();
}
function variant(v){return ({A:'A · Direta',B:'B · Consultiva',C:'C · Conversacional',FOLLOW_UP:'Follow-up',REPLY:'Resposta à conversa'})[v]||v}
function eventName(action){return ({MEETING_RECORDED:'Reunião registrada',LEAD_CREATED:'Lead cadastrado',ANALYZED:'Pesquisa analisada e score calculado',RESEARCH_UPDATED:'Pesquisa atualizada',APPROVE:'Mensagem aprovada',EDIT:'Mensagem editada',REJECT:'Mensagem rejeitada',CONTACT:'Contato manual registrado',STATUS:'Etapa comercial atualizada',DO_NOT_CONTACT:'Contato bloqueado',MESSAGE_SENT:'Mensagem aceita pela Meta',INSTAGRAM_RECEIVED:'Mensagem recebida no Instagram',CAMPAIGN_CREATED:'Campanha preparada',CAMPAIGN_AUTHORIZE:'Campanha autorizada',CAMPAIGN_PAUSE:'Campanha pausada',CAMPAIGN_CANCEL:'Campanha cancelada',CSV_IMPORTED:'CSV importado',DUPLICATE_SKIPPED:'Duplicado preservado',LEAD_DELETED:'Dados de lead excluídos',SETTINGS_UPDATED:'Configurações atualizadas'})[action]||action}
function messageCard(l,msg){const active=['PENDING','APPROVED'].includes(msg.state);const f=l.followups.find(f=>f.message_id===msg.id);return `<div class="card message-card"><div class="section-head"><div><h3>${esc(l.company)} · ${esc(variant(msg.variant))}</h3><p>${esc(l.analysis?.opportunities.map(o=>translate(o.service)).join(' · ')||'Contexto em revisão')}${f?' · Agendado para '+date(f.due_at):''}</p></div>${pill(msg.state)}</div><textarea id="message-${msg.id}" aria-label="Mensagem ${esc(variant(msg.variant))} para ${esc(l.company)}" ${active?'':'readonly'}>${esc(msg.body)}</textarea><div class="caption">${new TextEncoder().encode(msg.body).length} bytes · Revisão do texto exato antes de enviar</div>${active?`<div class="actions"><button data-message-action="review" data-lid="${l.id}" data-mid="${msg.id}">✦ Revisar texto</button><button data-message-action="edit" data-lid="${l.id}" data-mid="${msg.id}">Salvar edição</button><button data-message-action="approve" data-lid="${l.id}" data-mid="${msg.id}" class="primary">Aprovar</button><button data-message-action="reject" data-lid="${l.id}" data-mid="${msg.id}">Rejeitar</button><button data-copy="${msg.id}">Copiar</button>${msg.state==='APPROVED'?`<button data-message-action="contact" data-lid="${l.id}" data-mid="${msg.id}">Registrar contato manual</button>`:''}<button data-lead="${l.id}" class="trailing">Ver lead ↗</button></div><div id="review-${msg.id}"></div>`:''}</div>`}
function detail(id){selected=Number(id);const l=state.leads.find(l=>l.id===selected);if(!l){closeDetail();return}const a=l.analysis;let body=`<div class="detail-heading"><span class="company-logo">${initial(l.company)}</span><div><h2>${esc(l.company)}</h2><p>${esc(l.data.niche||'Nicho não informado')} · ${esc(l.data.city||'Cidade não informada')}</p></div><span class="score trailing">${l.score} pontos</span>${l.do_not_contact?pill('Não contatar','red'):pill(l.status)}</div><div class="detail-tabs">${[['analysis','Visão e análise'],['research','Pesquisa'],['messages','Abordagens'],['crm','CRM e histórico']].map(([key,label])=>`<button data-detail-tab="${key}" class="${detailTab===key?'active':''}">${label}</button>`).join('')}</div>`;
if(detailTab==='analysis')body+=`<div class="grid"><div class="card"><h3>Conheça o negócio</h3><div class="info-list">${[['Oferta principal',l.data.offer],['Público-alvo',l.data.audience],['Instagram',l.data.instagram?'@'+l.data.instagram:''],['Site',l.data.website],['E-mail comercial',l.data.email],['Telefone comercial',l.data.phone],['Responsável',l.data.owner],['Origem',l.data.source]].map(([label,value])=>`<div><span>${label.toUpperCase()}</span><strong>${esc(value||'Não verificado')}</strong></div>`).join('')}</div></div><div class="card"><div class="section-head"><h3>Por que este score?</h3>${pill(translate(a?.classification)||'Em análise')}</div>${a?.breakdown.map(c=>`<div class="health-line"><span>${esc(({icp:'Perfil ideal',opportunity:'Oportunidade clara',contact:'Contato disponível',offer:'Oferta registrada',activity:'Atividade verificada',agency_fit:'Perfil de agência',commercial_intent:'Intenção comercial',performance:'Tráfego e performance',automation:'IA e automação'})[c.criterion]||c.criterion)}</span><strong>${c.points} / ${c.maximum}</strong></div>`).join('')||''}<p class="caption">${esc(a?.explanation)}</p><p class="caption">Motor de oportunidades: regras locais. Informações fornecidas pelo operador; não verificadas independentemente.</p></div></div>${a?.opportunities.map(o=>`<div class="card service-card"><h3>${esc(translate(o.service))}</h3><p class="observation"><span>OBSERVAÇÃO REGISTRADA</span>${esc(o.evidence.note)}</p><p class="hypothesis"><span>HIPÓTESE DE OPORTUNIDADE</span>${esc(o.hypothesis)}</p><p class="caption">Fonte: ${esc(o.evidence.source)} · ${esc(o.evidence.observed_at||'Data não informada')}</p></div>`).join('')||`<div class="card">${empty('Precisamos de mais contexto','Nenhuma oportunidade clara foi registrada. Adicione evidências reais na pesquisa para preparar uma abordagem.','<button data-detail-tab="research">Completar pesquisa →</button>')}</div>`}<div class="banner"><span class="banner-symbol">◎</span><div><strong>Elegibilidade para Instagram</strong><p>${esc(state.eligibility[String(l.id)]||'Conversa recebida e vinculada; dentro da janela operacional de envio.')}</p></div><button data-view="inbox">Ver conversas ↗</button></div>`;
if(detailTab==='research'){const signals=[...state.config.icps,{signal:'recent_activity',name:'Atividade recente'}];body+=`<form id="research"><div class="card"><h3>Contexto comercial</h3><div class="form-grid">${field('offer','Oferta principal',l.data.offer)}${field('audience','Público-alvo',l.data.audience)}${field('acquisition','Como capta clientes?',l.data.acquisition)}${field('owner','Responsável',l.data.owner)}${field('next_action','Próxima ação',l.data.next_action)}<label class="wide">Notas de pesquisa<textarea name="notes">${esc(l.data.notes)}</textarea></label></div></div><div class="card"><h3>Sinais observados</h3><p class="muted">Marque somente o que você verificou. Cada sinal exige fonte e observação específica. Não ter encontrado um dado não comprova uma necessidade.</p>${signals.map(i=>{const e=l.data.evidence[i.signal]||{};return `<div class="evidence-form" data-signal="${esc(i.signal)}"><label class="check-label"><input name="verified" type="checkbox" ${e.verified?'checked':''}><strong>${esc(({no_landing:'Página de captação não encontrada na pesquisa',outdated_site:'Site desatualizado — verificado',no_cta:'Conteúdo analisado sem CTA',repetitive_questions:'Perguntas repetitivas no atendimento',manual_scheduling:'Agendamento realizado manualmente',recent_activity:'Atividade recente verificada'})[i.signal]||i.name)}</strong></label><div class="form-grid">${field('source','Fonte ou URL',e.source||'')}${field('observed_at','Data da observação',e.observed_at||'','date')}</div><label>O que você observou?<textarea name="note" placeholder="Uma observação específica e verdadeira">${esc(e.note||'')}</textarea></label></div>`}).join('')}<p class="caption">Salvar recalcula score e abordagens, invalida aprovações e pausa itens de campanhas relacionados.</p><div class="save-bar"><button class="primary">Salvar pesquisa e analisar ↗</button></div></div></form>`}
if(detailTab==='messages')body+=l.messages.filter(msg=>['PENDING','APPROVED','USED'].includes(msg.state)).map(msg=>messageCard(l,msg)).join('')||`<div class="card">${empty('A abordagem depende da pesquisa','Qualifique o lead com evidências antes de gerar mensagens.','<button data-detail-tab="research">Completar pesquisa ↗</button>')}</div>`;
if(detailTab==='crm')body+=`${meetingForm(l)}<form id="agenda-form" class="card"><h3>Agenda de próximas ações</h3><div class="form-grid">${field('owner','Responsável',l.data.owner)}${field('next_action','Próxima ação',l.data.next_action)}${field('next_action_due','Prazo',l.data.next_action_due||'','date')}</div><p class="caption">Salvar preserva score, mensagens e aprovações. Para concluir a ação, limpe a ação e o prazo ou registre o próximo passo.</p><button class="primary">Salvar agenda</button></form><form id="crm" class="card"><h3>Próximo passo comercial</h3><label>Etapa<select name="status">${state.statuses.map(s=>`<option value="${s}" ${s===l.status?'selected':''}>${esc(translate(s))}</option>`).join('')}</select></label><label>Resposta recebida ou nota da interação<textarea name="note" placeholder="Registre o que foi combinado"></textarea></label><div class="actions"><button class="primary">Atualizar etapa</button><button type="button" data-lead-action="do_not_contact" class="danger">Não contatar / opt-out</button><button type="button" data-lead-action="delete" class="danger trailing">Excluir dados do lead</button></div></form><div class="grid"><div class="card"><h3>Interações</h3>${l.interactions.map(e=>`<div class="timeline-event"><strong>${e.kind==='CONTACT'?'Contato realizado':'Atualização comercial'}</strong><small>${date(e.created_at)}</small><p>${esc(e.note)}</p></div>`).join('')||empty('Ainda sem interações','Registre um contato ou uma resposta para acompanhar o relacionamento.')}</div><div class="card"><h3>Follow-ups</h3>${l.followups.map(f=>`<div class="health-line"><span>${date(f.due_at)}</span>${pill(f.state)}</div>`).join('')||'<p class="muted">Sem follow-ups agendados.</p>'}<p class="caption">No Instagram, follow-up automático só é elegível enquanto a janela de conversa estiver aberta. As etapas manuais de dias 3 e 7 não autorizam envio fora dessa janela.</p><h3>Histórico de ações</h3>${l.audit_logs.map(e=>`<div class="timeline-event"><strong>${esc(eventName(e.action))}</strong><small>${date(e.created_at)}</small><p>${esc(e.detail)}</p></div>`).join('')}</div></div>`;
$('#detail-body').innerHTML=body;if(!$('#detail').open)$('#detail').showModal();bindDetailForms();}
function closeDetail(){selected=null;dirty=false;$('#detail').close()}
function splitNiches(s){return String(s).split(',').map(s=>s.trim()).filter(Boolean)}
function bindForms(){
if($('#search')){const filter=()=>{const text=$('#search').value.toLowerCase();const f=$('#lead-filter').value;$('#lead-table').innerHTML=table(state.leads.filter(l=>JSON.stringify([l.company,l.data.niche,l.data.city]).toLowerCase().includes(text)&&(f==='all'||f==='qualified'&&l.analysis?.qualified||f==='research'&&!l.analysis?.qualified||f==='eligible'&&!state.eligibility[String(l.id)])))};$('#search').oninput=filter;$('#lead-filter').onchange=filter}
if($('#create'))$('#create').onsubmit=e=>submitForm(e,async form=>{const r=await api('/api/leads',Object.fromEntries(new FormData(form)));dirty=false;await refresh();notify(r.duplicate?'Registro duplicado: dados existentes preservados.':'Lead cadastrado. Registre os sinais observados para qualificar.');detailTab='research';detail(r.id)});
if($('#settings'))$('#settings').onsubmit=e=>submitForm(e,async form=>{const data=Object.fromEntries(new FormData(form));data.min_lead_score=Number(data.min_lead_score);data.max_daily_actions=Number(data.max_daily_actions);data.target_niches=splitNiches(data.target_niches);data.excluded_niches=splitNiches(data.excluded_niches);await api('/api/settings',data);dirty=false;await refresh();notify('Configurações salvas. Campanhas ativas foram pausadas para revisão.')});
if($('#campaign-create'))$('#campaign-create').onsubmit=e=>submitForm(e,async form=>{const data=Object.fromEntries(new FormData(form));data.daily_limit=Number(data.daily_limit);data.interval_seconds=Number(data.interval_seconds);data.selections=[...form.querySelectorAll('input[name=lead]:checked')].map(i=>({lead_id:Number(i.value),message_id:Number(form.querySelector(`[data-campaign-message="${i.value}"]`).value)}));await api('/api/campaigns',data);dirty=false;await refresh();notify('Campanha preparada. Revise os textos e autorize os envios.')});
if($('#inbox-reply'))$('#inbox-reply').onsubmit=e=>submitForm(e,async form=>{const contact=state.inbox.find(c=>c.recipient_id===inboxId);await api('/api/inbox/reply',{lead_id:contact.lead_id,inbound_id:contact.events[0].provider_id,body:new FormData(form).get('body')});dirty=false;await refresh();notify('Resposta revisada e preparada. Confira o texto e autorize o envio.')});
if($('#automatic-settings'))$('#automatic-settings').onsubmit=e=>submitForm(e,async form=>{const data=Object.fromEntries(new FormData(form));data.enabled=form.elements.enabled.checked;data.per_contact_limit=Number(data.per_contact_limit);data.interval_seconds=Number(data.interval_seconds);await api('/api/automation/settings',data);dirty=false;await refresh();notify(data.enabled?'Atendimento automático ativado para novas mensagens.':'Atendimento automático desativado.')});
if($('#automatic-contact'))$('#automatic-contact').onsubmit=e=>submitForm(e,async()=>{const contact=state.inbox.find(c=>c.recipient_id===inboxId);await api('/api/inbox/automation',{recipient_id:inboxId,paused:!contact.automatic_paused});dirty=false;await refresh();notify('Controle da conversa atualizado.')});
if($('#prospect-search'))$('#prospect-search').onsubmit=e=>submitForm(e,async form=>{const r=await api('/api/prospecting/discover',Object.fromEntries(new FormData(form)));dirty=false;await refresh();notify(r.created+' candidatos adicionados; '+r.duplicates+' duplicados preservados.')});
document.querySelectorAll('.prospect-review').forEach(form=>form.onsubmit=e=>submitForm(e,async f=>{const data=Object.fromEntries(new FormData(f));data.verified=f.elements.verified.checked;data.id=Number(f.dataset.prospect);data.action='review';await api('/api/prospecting/update',data);dirty=false;await refresh();notify('Abordagem preparada para envio manual no Instagram.') }));
if($('#prospect-schedule'))$('#prospect-schedule').onsubmit=e=>submitForm(e,async form=>{await api('/api/prospecting/settings',{enabled:form.elements.enabled.checked,city:new FormData(form).get('city')});dirty=false;await refresh();notify('Captação diária atualizada.')});
if($('#inbox-link'))$('#inbox-link').onsubmit=e=>submitForm(e,async form=>{await api('/api/inbox/link',{recipient_id:inboxId,lead_id:Number(new FormData(form).get('lead_id'))});dirty=false;await refresh();notify('Conversa vinculada ao lead.')});
if($('#import-csv'))$('#import-csv').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{const file=$('#csv').files[0];if(!file)throw Error('Selecione um CSV.');if(file.size>1_900_000)throw Error('Arquivo excede o limite de importação.');const result=await api('/api/import',{csv:await file.text()});await refresh();$('#import-result').innerHTML=`<strong>${result.created} criados · ${result.duplicates} duplicados · ${result.errors.length} erros</strong>${result.errors.map(x=>`<div>Linha ${x.line}: ${esc(x.error)}</div>`).join('')}`}catch(error){notify(error.message)}finally{b.disabled=false}};
document.querySelectorAll('[data-campaign-message]').forEach(select=>select.onchange=()=>{const lid=Number(select.dataset.campaignMessage);const msg=state.leads.find(l=>l.id===lid).messages.find(m=>m.id===Number(select.value));$(`#campaign-preview-${lid}`).textContent=msg.body});
}
async function submitForm(event,operation){event.preventDefault();const form=event.currentTarget;const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{await operation(form)}catch(error){notify(error.message);if(selected)showDetailError(error.message)}finally{if(button)button.disabled=false}}
function showDetailError(message){let node=$('#detail-error');if(!node){node=document.createElement('p');node.id='detail-error';node.className='invalid';$('#detail-body').prepend(node)}node.textContent=message;node.scrollIntoView({block:'nearest'})}
function bindDetailForms(){if($('#meeting-form'))$('#meeting-form').onsubmit=e=>submitForm(e,async form=>{const data=Object.fromEntries(new FormData(form));for(const key of ['decision_maker','agency_fit','compatible_need'])data[key]=form.elements[key].checked;await api(`/api/leads/${selected}/meeting`,data);dirty=false;await refresh();notify('Reunião salva. Resultado atualizado.')});if($('#agenda-form'))$('#agenda-form').onsubmit=e=>submitForm(e,async form=>{await api(`/api/leads/${selected}/schedule`,Object.fromEntries(new FormData(form)));dirty=false;await refresh();notify('Agenda salva.')});if($('#research'))$('#research').onsubmit=e=>submitForm(e,async form=>{const data=Object.fromEntries(new FormData(form));data.evidence={};form.querySelectorAll('[data-signal]').forEach(node=>{data.evidence[node.dataset.signal]={verified:node.querySelector('[name=verified]').checked,source:node.querySelector('[name=source]').value.trim(),note:node.querySelector('[name=note]').value.trim(),observed_at:node.querySelector('[name=observed_at]').value}});await api(`/api/leads/${selected}/research`,data);dirty=false;detailTab='analysis';await refresh();notify('Pesquisa salva. Score e abordagens atualizados.')});if($('#crm'))$('#crm').onsubmit=e=>submitForm(e,async form=>{await api(`/api/leads/${selected}/status`,Object.fromEntries(new FormData(form)));dirty=false;await refresh();notify('Etapa e interação registradas.')})}
document.addEventListener('input',e=>{if(e.target.closest('form')||e.target.closest('.message-card'))dirty=true});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[data-lead]')){detailTab='analysis';detail(e.target.dataset.lead)}});
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-lead]');if(!b||b.disabled)return;try{
if(b.dataset.view){if(selected){if(dirty&&!confirm('Descartar alterações ainda não salvas?'))return;closeDetail()}setView(b.dataset.view);return}
if(b.dataset.lead){if(dirty&&!confirm('Descartar alterações ainda não salvas?'))return;dirty=false;detailTab='analysis';detail(b.dataset.lead);return}
if(b.dataset.detailTab){if(dirty&&!confirm('Descartar alterações ainda não salvas?'))return;dirty=false;detailTab=b.dataset.detailTab;detail(selected);return}
if(b.dataset.reviewFilter){if(dirty&&!confirm('Descartar alterações ainda não salvas?'))return;reviewFilter=b.dataset.reviewFilter;dirty=false;render();return}
if(b.dataset.inbox){inboxId=b.dataset.inbox;render();return}
if(b.dataset.copyProspect){const c=state.prospecting.candidates.find(c=>c.id===Number(b.dataset.copyProspect));await navigator.clipboard.writeText(c.approach);notify('Abordagem copiada. Envie manualmente no Instagram.');return}
if(b.dataset.rejectProspect){await api('/api/prospecting/update',{id:Number(b.dataset.rejectProspect),action:'reject'});await refresh();notify('Candidato descartado.');return}
if(b.dataset.copy){await navigator.clipboard.writeText($('#message-'+b.dataset.copy).value);notify('Mensagem copiada.');return}
if(b.dataset.messageAction){b.disabled=true;const action=b.dataset.messageAction,lid=Number(b.dataset.lid),mid=Number(b.dataset.mid),body=$('#message-'+mid).value;
if(action==='review'){const result=await api(`/api/leads/${lid}/review`,{body});$('#review-'+mid).className='review-result';$('#review-'+mid).innerHTML=`<strong>${result.passed?'Checklist passou':'Ajustes necessários'}</strong> · ${esc(result.engine)}${result.issues.length?`<ul class="list">${result.issues.map(i=>`<li>${esc(i)}</li>`).join('')}</ul>`:''}<div>${esc(result.note)}</div>${result.ai?.suggestion?`<p>Sugestão para revisão: ${esc(result.ai.suggestion)}</p>`:''}`;return}
if(action==='contact'&&!confirm('Você já realizou manualmente o contato usando exatamente este texto aprovado?'))return;
await api(`/api/leads/${lid}/${action}`,{message_id:mid,body});dirty=false;await refresh();notify(action==='contact'?'Contato manual registrado.':'Revisão registrada. Para envio real, adicione a mensagem a uma campanha.');return}
if(b.dataset.reconcile){if(!confirm('Você conferiu a conversa diretamente no Instagram? Esta declaração será registrada na auditoria.'))return;b.disabled=true;await api(`/api/campaigns/${b.dataset.campaign}/reconcile`,{item_id:Number(b.dataset.reconcile),outcome:b.dataset.outcome});await refresh();notify('Resultado reconciliado pelo operador. Nenhum reenvio automático foi feito.');return}
if(b.dataset.campaignAction){b.disabled=true;const action=b.dataset.campaignAction;const campaign=state.campaigns.find(c=>c.id===Number(b.dataset.campaign));if(action==='authorize'&&!confirm(`Autorizar o envio real pelo Instagram dos textos apresentados na campanha “${campaign.name}”, respeitando ${campaign.daily_limit} mensagens/dia e intervalo de ${campaign.interval_seconds}s? A autorização expira em 24 horas.`))return;await api(`/api/campaigns/${campaign.id}/${action}`,{});await refresh();notify(action==='authorize'?'Campanha autorizada. O worker enviará os itens elegíveis dentro dos limites.':'Campanha atualizada.');return}
if(b.dataset.leadAction){const action=b.dataset.leadAction;if(action==='delete'&&!confirm('Excluir definitivamente este lead, suas mensagens, pesquisa e histórico?'))return;b.disabled=true;await api(`/api/leads/${selected}/${action}`,{});dirty=false;await refresh();notify(action==='delete'?'Dados do lead excluídos.':'Opt-out registrado. Novas abordagens foram bloqueadas.')}
}catch(error){notify(error.message);if(selected)showDetailError(error.message)}finally{b.disabled=false}});
$('#close').onclick=()=>{if(dirty&&!confirm('Descartar alterações ainda não salvas?'))return;closeDetail()};$('#detail').addEventListener('cancel',e=>{if(dirty&&!confirm('Descartar alterações ainda não salvas?')){e.preventDefault();return}selected=null;dirty=false});$('#refresh').onclick=()=>{if(dirty&&!confirm('Descartar alterações ainda não salvas?'))return;dirty=false;refresh().then(()=>notify('Dados atualizados.')).catch(e=>notify(e.message))};
setInterval(()=>{if(!dirty&&!selected&&['overview','campaigns','inbox','report'].includes(view))refresh().catch(()=>{})},15000);
$('#content').innerHTML='<div class="loading">Carregando sua central de operações…</div>';refresh().catch(e=>notify(e.message));

function prospectResearch(c){const r=c.research;if(!r?.status)return '';return `<div class="message-preview"><strong>Pesquisa e possível necessidade</strong><p><b>Observado:</b> ${esc(r.fact)}</p><p><b>Oportunidade a validar:</b> ${esc(r.need)}</p><p><b>Antes de enviar:</b> ${esc(r.check)}</p>${r.source&&/^https?:\/\//.test(r.source)?`<a href="${esc(r.source)}" target="_blank" rel="noopener">Conferir fonte ↗</a>`:''}<p class="caption">${esc(r.date)} · Conteúdo dos posts não auditado visualmente.</p></div>`}

$('#logout').onclick=async()=>{try{await api('/api/auth/logout',{});window.location.replace('/login')}catch(e){notify(e.message)}};

